package com.erp.reimbursement.repository; import org.springframework.data.jpa.repository.JpaRepository; import com.erp.reimbursement.entity.Department; import java.util.*; public interface DepartmentRepository extends JpaRepository<Department,Long> { Optional<Department> findByNameIgnoreCase(String name); List<Department> findAllByActiveTrueOrderByNameAsc(); List<Department> findAllByOrderByNameAsc(); }
